result.output:
            own = owned_project_ids(self.all_projects, self.current_employee_id)
            result = [p for p in result if str(p.real_id) in own]
        if self.employee_scope:
            mine = managed_employee_ids(
                self.available_employees, self.current_employee_id
            )
            result = [
                p for p in result if any(str(e.real_id) in mine for e in p.employees)
            ]
        return filter_project_blocks(
            result,
            self.weeks,
            self.current_week_key,
            project_ids=self.project_filter,
            role_ids=self.role_filter,
            employee_ids=self.employee_filter,
            role_id_lookup=self.role_id_lookup,
            available_employee_ids=(
                {e.id for e in self._filter_employees(self.employee_blocks)}
                if self.available_only
                else None
            ),
        )

    @rx.var(cache=True, backend=True)
    def projects(self) -> list[ProjectBlock]:
        return self.project_blocks

    @rx.var(cache=True)
    def has_dirty(self) -> bool:
        return len(self.dirty_keys) > 0 or len(self.hidden_edits) > 0

    @rx.var(cache=True)
    def current_week_key(self) -> str:
        """Current week as of the last populate, so summaries match the columns."""
        return self.current_week or current_week_key()

    # === Loading ===

    async def _fetch_holidays(self, num_weeks: int) -> set[dt.date]:
        """Load public holidays covering the rolling planning window."""

        role_abbrev_by_name = {r.name: r.abbreviation for r in self.available_roles}
        emp_meta, absence_map = build_employee_meta(
            self.available_employees, wks, role_abbrev_by_name
        )
        proj_meta, proj_idx = build_project_meta(self.available_projects)
        cells, role_lookup, role_id_lookup, pairs = ingest_allocations(
            allocations, assignments, proj_idx, set(wks)
        )
        wire_pairs(emp_meta, proj_idx, pairs)
        self._cell_role_ids = cell_role_ids(allocations, proj_idx, set(wks))

        self.weeks = weeks
        self.current_week = current_week_key()
        self.month_spans = spans
        self.holiday_dates = sorted(holiday_dates)
        self.saved_cells = dict(cells)
        self.grid_revision += 1
        self.employee_meta = emp_meta
        self.project_meta = proj_meta
        self.role_lookup = role_lookup
        self.role_id_lookup = role_id_lookup
        self.absence_days = absence_map
        visible, hidden = split_edits(
            pending, self._editable_rows(), {w.key for w in weeks}
        )


def employee_summary(block: EmployeeBlock, from_key: str) -> tuple[float, float]:
    """Planned and available person-days from ``from_key`` onward.

    Planned sums all project cells; available sums the free days of weeks
    that still have capacity (overbooked weeks count as zero).
    """
    planned = sum(
        cell.value
        for project in block.projects
        for cell in project.cells
        if cell.week_key >= from_key
    )
    available = sum(
        max(cell.value, 0.0) for cell in block.gesamt if cell.week_key >= from_key
    )
    return round(planned, 2), round(available, 2)


def without_internal_projects(blocks: list[EmployeeBlock]) -> list[EmployeeBlock]:
    """Copies of the blocks without internal project rows; totals stay as is."""
    return [
        block.model_copy(
            update={"projects": [p for p in block.projects if not p.is_internal]}
        )
        for block in blocks
    ]


def without_idle_projects(blocks: list[ProjectBlock]) -> list[ProjectBlock]:
    """Drop projects without any planned effort in the visible range."""
    return [
        block
        for block in blocks
        if any(cell.value > 0 for row in block.employees for cell in row.cells)
    ]


def filter_project_blocks(
    blocks: list[ProjectBlock],
    weeks: list[WeekColumn],
    from_key: str,
    *,
    project_ids: list[str],
    role_ids: list[str],
    employee_ids: list[str],
    role_id_lookup: dict[str, int],
    available_employee_ids: set[str] | None = None,
) -> list[ProjectBlock]:
    """Filter projects and rebuild totals when availability limits their rows."""
    result = blocks
    if available_employee_ids is not None:
        result = []
        for block in blocks:
            employees = [
                employee
                for employee in block.employees
                if employee.emp_id in available_employee_ids
            ]
            if not employees:
                continue
            filtered = block.model_copy(update={"employees": employees})
            filtered.gesamt = compute_project_gesamt(weeks, filtered)
            filtered.planned_days, filtered.role_totals = project_summary(
                filtered, from_key
            )
            result.append(filtered)
    if project_ids:
        result = [p for p in result if str(p.real_id) in project_ids]
    if role_ids:
        result = [
            p
            for p in result
            if any(
                str(role_id_lookup.get(f"{e.emp_id}|{p.real_id}")) in role_ids
                for e in p.employees
            )
        ]
    if employee_ids:
        result = [
            p
            for p in result
            if any(str(e.real_id) in employee_ids for e in p.employees)
        ]
    return result


